package com.sunmo.stockplatform.analytics.application;
import com.sunmo.stockplatform.analytics.api.PerformanceDtos.*;import com.sunmo.stockplatform.analytics.domain.*;import com.sunmo.stockplatform.analytics.infrastructure.DetectionPerformanceRepository;import com.sunmo.stockplatform.common.error.*;import com.sunmo.stockplatform.scanner.infrastructure.ScannerDetectionRepository;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.Instant;import java.util.*;import java.util.function.Function;
@Service @Transactional(readOnly=true)
public class ScannerAnalyticsService {private final ScannerDetectionRepository detections;private final DetectionPerformanceRepository performances;public ScannerAnalyticsService(ScannerDetectionRepository detections,DetectionPerformanceRepository performances){this.detections=detections;this.performances=performances;}public PerformanceResponse performance(long detectionId){return performances.findById(detectionId).map(PerformanceResponse::from).orElseThrow(()->new ApplicationException(ErrorCode.INVALID_REQUEST,HttpStatus.NOT_FOUND,"Performance not found: "+detectionId));}public AnalyticsResponse analytics(Long settingId,Instant from,Instant to){var rows=detections.findByDetectedAtBetweenOrderByDetectedAtAsc(from,to).stream().filter(d->settingId==null||d.getSetting().getId().equals(settingId)).map(d->performances.findById(d.getId()).orElse(null)).filter(Objects::nonNull).toList();long completed=rows.stream().filter(p->p.getStatus()==PerformanceStatus.COMPLETED).count(),missing=rows.stream().filter(p->p.getStatus()==PerformanceStatus.DATA_MISSING).count();return new AnalyticsResponse(rows.size(),completed,missing,win(rows,DetectionPerformance::getReturn5m),win(rows,DetectionPerformance::getReturnClose),avg(rows,DetectionPerformance::getReturn5m),avg(rows,DetectionPerformance::getReturn10m),avg(rows,DetectionPerformance::getReturn30m),avg(rows,DetectionPerformance::getReturn60m),avg(rows,DetectionPerformance::getReturnClose),"performance-v1");}private BigDecimal avg(List<DetectionPerformance> rows,Function<DetectionPerformance,BigDecimal> getter){var values=rows.stream().map(getter).filter(Objects::nonNull).toList();if(values.isEmpty())return null;return values.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(values.size()),6,RoundingMode.HALF_UP);}private BigDecimal win(List<DetectionPerformance> rows,Function<DetectionPerformance,BigDecimal> getter){var values=rows.stream().map(getter).filter(Objects::nonNull).toList();if(values.isEmpty())return null;long wins=values.stream().filter(v->v.signum()>0).count();return BigDecimal.valueOf(wins).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(values.size()),6,RoundingMode.HALF_UP);}}
